package memory

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// IndexFile is the index loaded at the start of every session.
const IndexFile = "MEMORY.md"

// indexLabels holds the index texts per language. Only the program writes the index,
// so its headings can follow the user's language without the program ever reading them.
var indexLabels = map[string]map[string]string{
	"en": {
		"title":     "Memory index",
		"generated": "Generated by augmented brain after every change: do not edit it by hand. To work on a subject, open its area first.",
		"profile":   "Profile",
		"rules":     "Rules",
		"areas":     "Areas",
		"tasks":     "Live tasks",
		"noarea":    "No area",
		"none":      "none yet",
		"someday":   "Someday: %d tasks, not loaded here.",
		"waits":     "waits on",
		"next":      "next",
	},
	"es": {
		"title":     "Índice de la memoria",
		"generated": "Lo genera augmented brain tras cada cambio: no lo edites a mano. Para trabajar en un tema, abre primero su área.",
		"profile":   "Perfil",
		"rules":     "Reglas",
		"areas":     "Áreas",
		"tasks":     "Tareas vivas",
		"noarea":    "Sin área",
		"none":      "todavía ninguna",
		"someday":   "Algún día: %d tareas, no se cargan aquí.",
		"waits":     "espera a",
		"next":      "siguiente",
	},
}

// Index builds the text of MEMORY.md: one line per profile, rule and area, and the live
// tasks grouped by area. Closed and someday tasks stay out to keep it short.
func (m *Memory) Index(lang string) string {
	l, ok := indexLabels[lang]
	if !ok {
		l = indexLabels["en"]
	}
	var b strings.Builder
	line := func(n *Note, extra string) {
		fmt.Fprintf(&b, "- [%s](%s)", n.Header.Title, n.Path)
		if n.Header.Summary != "" {
			fmt.Fprintf(&b, " — %s", n.Header.Summary)
		}
		b.WriteString(extra + "\n")
	}
	section := func(title string, notes []*Note) {
		fmt.Fprintf(&b, "\n## %s\n", title)
		if len(notes) == 0 {
			fmt.Fprintf(&b, "- (%s)\n", l["none"])
		}
		for _, n := range notes {
			line(n, "")
		}
	}

	fmt.Fprintf(&b, "# %s\n\n%s\n", l["title"], l["generated"])
	if p := m.OfType("profile"); len(p) > 0 {
		section(l["profile"], p)
	}
	section(l["rules"], m.OfType("rule"))
	areas := m.OfType("area")
	section(l["areas"], areas)

	fmt.Fprintf(&b, "\n## %s\n", l["tasks"])
	byArea := map[string][]*Note{}
	someday := 0
	for _, t := range m.OfType("task") {
		switch t.Header.Status {
		case "closed":
		case "someday":
			someday++
		default:
			byArea[t.Header.Area] = append(byArea[t.Header.Area], t)
		}
	}
	if len(byArea) == 0 {
		fmt.Fprintf(&b, "- (%s)\n", l["none"])
	}
	groups := make([]string, 0, len(byArea))
	for a := range byArea {
		groups = append(groups, a)
	}
	sort.Strings(groups) // "" (no area) sorts first
	for _, a := range groups {
		title := l["noarea"]
		if n, ok := m.Notes[a]; ok {
			title = n.Header.Title
		}
		fmt.Fprintf(&b, "\n### %s\n", title)
		for _, t := range byArea[a] {
			line(t, fmt.Sprintf(" · %s · %s %s · %s: %s",
				t.Header.Status, l["waits"], t.Header.WaitingOn, l["next"], t.Header.Next))
		}
	}
	if someday > 0 {
		fmt.Fprintf(&b, "\n"+l["someday"]+"\n", someday)
	}
	return b.String()
}

// WriteIndex writes MEMORY.md and reports whether it changed.
func (m *Memory) WriteIndex(lang string) (bool, error) {
	path := filepath.Join(m.Dir, IndexFile)
	text := m.Index(lang)
	if old, err := os.ReadFile(path); err == nil && string(old) == text {
		return false, nil
	}
	return true, os.WriteFile(path, []byte(text), 0o644)
}
